create extension if not exists pgcrypto;
create table public.sites (id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,name text not null check(char_length(name) between 2 and 100),slug text not null unique check(slug ~ '^[a-z0-9][a-z0-9-]{1,46}[a-z0-9]$'),status text not null default 'draft' check(status in('draft','published','suspended')),plan text not null default 'free' check(plan in('free','pro','custom')),language text not null default 'pt-BR' check(language in('pt-BR','es-VE')),template_id text not null,settings jsonb not null default '{}',published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index one_free_site_per_owner on public.sites(owner_id) where plan='free';
create table public.site_domains(id uuid primary key default gen_random_uuid(),site_id uuid not null references public.sites(id) on delete cascade,hostname text not null unique,type text not null default 'subdomain' check(type in('subdomain','custom')),verified boolean not null default false,"primary" boolean not null default false);
create table public.site_sections(id uuid primary key default gen_random_uuid(),site_id uuid not null references public.sites(id) on delete cascade,type text not null check(type in('hero','about','services','gallery','testimonials','faq','contact')),variant text not null,position integer not null check(position between 1 and 20),visible boolean not null default true,content jsonb not null default '{}',settings jsonb not null default '{}',unique(site_id,position));
create table public.site_assets(id uuid primary key default gen_random_uuid(),site_id uuid not null references public.sites(id) on delete cascade,owner_id uuid not null references auth.users(id) on delete cascade,path text not null unique,mime_type text not null check(mime_type in('image/jpeg','image/png','image/webp')),size integer not null check(size between 1 and 5242880),created_at timestamptz not null default now());
create table public.site_leads(id uuid primary key default gen_random_uuid(),site_id uuid not null references public.sites(id) on delete cascade,name text not null,email text,phone text,message text not null,created_at timestamptz not null default now());
create table public.templates(id text primary key,name text not null,segment text not null,is_free boolean not null default true,active boolean not null default true,created_at timestamptz not null default now());
insert into public.templates(id,name,segment) values('services','Empresa & Serviços','Serviços'),('legal','Advocacia','Jurídico'),('beauty','Beleza & Barbearia','Beleza');
alter table public.sites enable row level security; alter table public.site_domains enable row level security; alter table public.site_sections enable row level security; alter table public.site_assets enable row level security; alter table public.site_leads enable row level security; alter table public.templates enable row level security;
create policy "owners manage sites" on public.sites for all using(owner_id=auth.uid()) with check(owner_id=auth.uid()); create policy "published sites public" on public.sites for select using(status='published');
create policy "owners manage domains" on public.site_domains for all using(exists(select 1 from public.sites s where s.id=site_id and s.owner_id=auth.uid())) with check(exists(select 1 from public.sites s where s.id=site_id and s.owner_id=auth.uid()));
create policy "owners manage sections" on public.site_sections for all using(exists(select 1 from public.sites s where s.id=site_id and s.owner_id=auth.uid())) with check(exists(select 1 from public.sites s where s.id=site_id and s.owner_id=auth.uid())); create policy "published sections public" on public.site_sections for select using(exists(select 1 from public.sites s where s.id=site_id and s.status='published'));
create policy "owners manage assets" on public.site_assets for all using(owner_id=auth.uid() and exists(select 1 from public.sites s where s.id=site_id and s.owner_id=auth.uid())) with check(owner_id=auth.uid() and exists(select 1 from public.sites s where s.id=site_id and s.owner_id=auth.uid()));
create policy "owners read leads" on public.site_leads for select using(exists(select 1 from public.sites s where s.id=site_id and s.owner_id=auth.uid())); create policy "public submits published leads" on public.site_leads for insert with check(exists(select 1 from public.sites s where s.id=site_id and s.status='published'));
create policy "templates readable" on public.templates for select using(active=true);
create or replace function public.move_site_section(target_site uuid,target_section uuid,direction text) returns void language plpgsql security invoker as $$ declare current_position integer; other_position integer; begin select position into current_position from public.site_sections where id=target_section and site_id=target_site; other_position:=case when direction='up' then current_position-1 else current_position+1 end; update public.site_sections set position=case when id=target_section then other_position when position=other_position then current_position else position end where site_id=target_site and (id=target_section or position=other_position); end $$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('site-assets','site-assets',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy "owners upload site assets" on storage.objects for insert to authenticated with check(bucket_id='site-assets' and (storage.foldername(name))[1]=auth.uid()::text); create policy "owners update site assets" on storage.objects for update to authenticated using(bucket_id='site-assets' and (storage.foldername(name))[1]=auth.uid()::text); create policy "owners delete site assets" on storage.objects for delete to authenticated using(bucket_id='site-assets' and (storage.foldername(name))[1]=auth.uid()::text); create policy "site assets public" on storage.objects for select using(bucket_id='site-assets');
